const animal = { eats: true, hello() { return 'hi from ' + this.name; } };
const dog = Object.create(animal);   // dog's prototype is animal
dog.name = 'Rex';                    // own property
dog.barks = true;

console.log('own keys of dog:', Object.keys(dog));
console.log('dog.barks (own):', dog.barks);
console.log('dog.eats (1 hop up):', dog.eats);
