// A polyfill of the "new" operator
function myNew(C, ...args) {
  // step 2: link to C.prototype (fallback Object.prototype)
  const proto = (typeof C.prototype === 'object' && C.prototype) || Object.prototype;
  const obj = Object.create(proto);          // step 1: fresh object
  const r = C.apply(obj, args);              // step 3: run constructor with this = obj
  // step 4: an object result wins, primitives are ignored
  return (r !== null && (typeof r === 'object' || typeof r === 'function')) ? r : obj;
}

