// Prototype pollution via an unsafe merge, and a safe version
function badMerge(t, s) {
  for (const k in s) {
    if (typeof s[k] === 'object' && s[k] !== null) {
      t[k] = t[k] || {};
      badMerge(t[k], s[k]);
    } else t[k] = s[k];
  }
  return t;
}
const evil = JSON.parse('{"__proto__": {"isAdmin": true}}');
console.log('JSON.parse alone, own key:', Object.keys(evil), '({}).isAdmin:', ({}).isAdmin);

badMerge({}, evil);
console.log('after bad merge, ({}).isAdmin:', ({}).isAdmin);   // polluted!
delete Object.prototype.isAdmin;                                  // clean up

function safeMerge(t, s) {
  for (const k of Object.keys(s)) {
    if (k === '__proto__' || k === 'constructor' || k === 'prototype') continue;
    if (s[k] && typeof s[k] === 'object') {
      if (!Object.hasOwn(t, k)) t[k] = {};
      safeMerge(t[k], s[k]);
    } else t[k] = s[k];
  }
  return t;
}
const out = safeMerge({}, JSON.parse('{"a":{"b":1},"__proto__":{"isAdmin":true}}'));
console.log('safe result:', JSON.stringify(out), '({}).isAdmin:', ({}).isAdmin);

// Mixins via class factories vs object-copy mixins
