// Shape stability: consistent property order vs changing shapes (rough timing)
class Stable { constructor(i) { this.a = i; this.b = i + 1; this.c = i + 2; } }

function makeMixed(i) {
  const o = {};
  if (i % 2) { o.a = i; o.b = i + 1; o.c = i + 2; }
  else { o.c = i + 2; o.b = i + 1; o.a = i; }     // different order, different shape
  return o;
}
function sum(arr) {
  let s = 0;
  for (let k = 0; k < arr.length; k++) s += arr[k].a + arr[k].b + arr[k].c;
  return s;
}
const N = 200000;
const stable = Array.from({ length: N }, (_, i) => new Stable(i));
const mixed = Array.from({ length: N }, (_, i) => makeMixed(i));

function time(label, arr) {
  let r = 0;
  const t = process.hrtime.bigint();
  for (let rep = 0; rep < 20; rep++) r = sum(arr);
  const ms = Number(process.hrtime.bigint() - t) / 1e6;
  console.log(label, 'checksum', r, '| timed:', ms >= 0);
}
time('stable shape:', stable);
time('mixed shapes:', mixed);
console.log('same property order for all Stable?',
  new Set(stable.slice(0, 100).map(o => Object.keys(o).join())).size === 1);
console.log('distinct key orders in mixed:',
  new Set(mixed.slice(0, 100).map(o => Object.keys(o).join())).size);
